'use client';
import { useState } from 'react';
import Link from 'next/link';
import type { Scene } from '@seapilot/contracts';
import { CUSTOMER_MESSAGES, getSuggestion } from '@seapilot/demo';
import { useDemo } from '@seapilot/demo/react';
import { Input, Textarea, Label, Tabs, TabsList, TabsTrigger, TabsContent, Alert, AlertDescription, Avatar, Badge, Brand, Button, Sheet, EvidenceTile, EmptyState, ArrowLeft, ArrowRight, CalendarDays, Plus, CheckCheck, Clock3, Inbox, LifeBuoy, Link2, MessageSquare, PanelRight, RotateCcw, Search, Send, ShieldCheck } from '@seapilot/ui';
import { CasePanel } from './case-panel';

export function Workspace({ demoEnabled }: { demoEnabled: boolean }) {
  const { state, busy, error, notice, perform, reset } = useDemo('returning');
  const [selected, setSelected] = useState('CONV2');
  const [query, setQuery] = useState('');
  const [needsReply, setNeedsReply] = useState(false);
  const [showThread, setShowThread] = useState(true);
  const [details, setDetails] = useState(false);
  const [evidence, setEvidence] = useState<'A' | 'B' | null>(null);
  const [help, setHelp] = useState(false);
  const [drafts, setDrafts] = useState<Record<string, { text: string; revision: number }>>({});
  const [rejected, setRejected] = useState<Record<string, boolean>>({});
  const [dismissedMatch, setDismissedMatch] = useState<Record<string, boolean>>({});
  const conversation = state.conversations.find(c => c.id === selected);
  const linked = !!conversation?.caseId;
  const suggestion = getSuggestion(state, selected);
  const draft = drafts[selected]?.text ?? '';
  const staleDraft = !!draft && drafts[selected]?.revision !== state.revision;
  const conversations = state.conversations.slice().reverse().filter(c => (!needsReply || c.messages.at(-1)?.role === 'customer') && `${c.title} ${c.id} Lan Nguyen DH001`.toLowerCase().includes(query.toLowerCase()));
  const agent = state.day ? 'Binh' : 'An';
  function chooseScene(scene: Scene) {
    reset(scene); setSelected(scene === 'start' ? '' : scene === 'first' ? 'CONV1' : 'CONV2');
    setDrafts({}); setRejected({}); setDismissedMatch({}); setQuery(''); setNeedsReply(false); setShowThread(scene !== 'start'); setDetails(false);
  }
  async function approveReply() {
    if (await perform({ type: 'approveReply', conversationId: selected, text: draft, expectedRevision: drafts[selected]?.revision ?? state.revision }, 'Reply approved and saved in this local demo.')) setDrafts(previous => ({ ...previous, [selected]: { text: '', revision: state.revision } }));
  }
  async function escalate() {
    if (await perform({ type: 'escalate', conversationId: selected }, 'Escalation recorded. Review the updated reply before sending.')) setDrafts(previous => ({ ...previous, [selected]: { text: '', revision: state.revision } }));
  }
  const panel = <CasePanel state={state} linked={linked} suggestion={suggestion} busy={busy} onEvidence={setEvidence} onUseDraft={() => { if (suggestion) { setDrafts(previous => ({ ...previous, [selected]: { text: suggestion.draft, revision: state.revision } })); setDetails(false); } }} onEscalate={() => void escalate()} rejected={!!rejected[selected]} onRestore={() => setRejected(previous => ({ ...previous, [selected]: false }))} />;
  return <main className="workspace" id="main">
    <nav className="app-rail" aria-label="Workspace navigation"><Brand compact /><div className="rail-nav"><Button variant="ghost" size="icon" className="rail-active" aria-label="Conversations" onClick={() => setShowThread(false)}><Inbox /></Button></div><div className="rail-bottom"><Button variant="ghost" size="icon" aria-label="About this demo" onClick={() => setHelp(true)}><LifeBuoy /></Button><Avatar name={agent} /></div></nav>
    <div className="workspace-body">
      <header className="workspace-top"><div className="row"><h1>Conversations</h1><span className="top-subtitle">Every conversation. One continuous case.</span></div><div className="row"><Badge tone="green">Local demo</Badge><span className="agent-label">On shift</span><Avatar small name={agent} /><span className="agent-name">{agent}</span></div></header>
      <div className={`workspace-columns ${showThread ? 'show-thread' : ''}`}>
        <aside className="inbox-pane" aria-label="Conversation inbox"><div className="inbox-header"><h2>Team inbox<span className="count">{state.conversations.length}</span></h2></div><Label className="search-box"><Search size={14} /><span className="sr-only">Search conversations</span><Input placeholder="Search conversations…" value={query} onChange={e => setQuery(e.target.value)} /></Label><Tabs value={needsReply ? 'needs' : 'all'} onValueChange={value => setNeedsReply(value === 'needs')}><TabsList className="inbox-tabs" aria-label="Filter conversations"><TabsTrigger className="inbox-tab" value="all">All conversations</TabsTrigger><TabsTrigger className="inbox-tab" value="needs">Needs reply</TabsTrigger></TabsList><TabsContent value={needsReply ? 'needs' : 'all'} className="inbox-tab-content">
          {conversations.map(c => <Button variant="ghost" key={c.id} className={`conversation-item ${selected === c.id ? 'selected' : ''}`} onClick={() => { setSelected(c.id); setShowThread(true); }} aria-current={selected === c.id ? 'true' : undefined}><div className="row"><Avatar small name="Lan Nguyen" /><strong className="small">Lan Nguyen</strong><time>{c.day ? '09:41' : 'Yesterday'}</time></div><h3>{c.title}</h3><p>{c.messages.at(-1)?.text ?? 'No messages yet'}</p><div className="case-ref">{c.caseId ? <><Link2 size={11} />{c.caseId}<span>·</span><span>Order DH001</span></> : <><span>●</span><span>No case linked</span></>}</div></Button>)}
          {!conversations.length && <p className="empty-inbox">{query ? 'No conversations match your search.' : 'No conversations here yet. Load a demo scene to begin.'}</p>}</TabsContent></Tabs><div className="inbox-footer">All conversations stay here for follow-up.</div>
        </aside>
        <section className="thread-pane" aria-label="Selected conversation">
          {conversation ? <><div className="thread-header"><div className="row"><Button variant="ghost" size="icon" className="mobile-back" aria-label="Back to inbox" onClick={() => setShowThread(false)}><ArrowLeft /></Button><Avatar name="Lan Nguyen" /><div><h2>{conversation.title}</h2><p>Lan Nguyen <span>·</span> {conversation.id} <span>·</span> Web chat</p></div></div><div className="row"><Badge tone={linked ? 'green' : 'neutral'}>{linked ? state.case?.status === 'waiting_ops' ? 'Waiting on ops' : 'Open case' : 'New'}</Badge><Button variant="outline" size="icon" className="details-trigger" aria-label="Open case details" onClick={() => setDetails(true)}><PanelRight /></Button></div></div>
          {!linked && <div className="link-banner">{state.case ? dismissedMatch[selected] ? <><h3>Suggested match dismissed</h3><p>This conversation has not been linked. Review the match when you’re ready.</p><Button size="sm" variant="outline" onClick={() => setDismissedMatch(previous => ({ ...previous, [selected]: false }))}>Review match</Button></> : <><h3><Link2 size={15} />Continue case CS001?</h3><p>Same customer, same order, same missing cap. Keep the earlier conversation and evidence together.</p><div className="row"><Button size="sm" disabled={busy} onClick={() => void perform({ type: 'link', conversationId: selected }, 'Conversation linked. Earlier context is now available.')}><Link2 />Link to CS001</Button><Button size="sm" variant="ghost" disabled={busy} onClick={() => setDismissedMatch(previous => ({ ...previous, [selected]: true }))}>Not this case</Button></div></> : <><h3><Link2 size={15} />Keep this request together</h3><p>No case exists yet. Create one to record the request and attachment.</p><Button size="sm" disabled={busy} onClick={() => void perform({ type: 'createCase', conversationId: selected }, 'Case CS001 created and linked.')}><Plus />Create case</Button></>}</div>}
          <div className="thread-scroll" role="log" aria-live="polite" aria-label="Conversation messages"><div className="day-divider">{conversation.day ? 'Today, October 31' : 'Previous contact'}</div>{linked && <div className="thread-label"><Link2 size={11} style={{ display: 'inline', marginRight: 4 }} />Linked to CS001 · earlier context is in the case panel</div>}{conversation.messages.map(message => <article key={message.id} className={`message ${message.role === 'agent' ? 'own' : ''}`}><Avatar small name={message.role === 'customer' ? 'Lan Nguyen' : message.agent ?? 'Support'} /><div className="message-body"><div className="message-meta"><strong>{message.role === 'customer' ? 'Lan Nguyen' : `${message.agent ?? 'Support'} · Agent`}</strong><time>{message.time}</time>{message.role === 'agent' && <CheckCheck size={12} />}</div><div className="bubble">{message.text}</div>{message.attachment && <EvidenceTile parcel={message.attachment === 'parcel-a' ? 'A' : 'B'} onClick={() => setEvidence(message.attachment === 'parcel-a' ? 'A' : 'B')} />}</div></article>)}</div>
          <form className="composer" onSubmit={e => { e.preventDefault(); void approveReply(); }}><div className="row between reply-label"><span>Reply to Lan Nguyen</span><span className="row"><ShieldCheck size={12} />Your approval, every time</span></div><div className="composer-box"><Label htmlFor="agent-reply" className="sr-only">Draft reply</Label><Textarea id="agent-reply" placeholder={linked ? 'Write a reply, or use the suggested next step…' : 'Link this conversation to a case to reply…'} value={draft} disabled={!linked || busy} maxLength={4000} onChange={e => setDrafts(previous => ({ ...previous, [selected]: { text: e.target.value, revision: previous[selected]?.text ? previous[selected].revision : state.revision } }))} /><div className="composer-tools"><Button variant="ghost" size="sm" disabled={!draft || busy} onClick={() => { setDrafts(previous => ({ ...previous, [selected]: { text: '', revision: state.revision } })); setRejected(previous => ({ ...previous, [selected]: true })); }}>Reject draft</Button><Button type="submit" disabled={!linked || !draft.trim() || busy || staleDraft}>{busy ? 'Saving…' : 'Approve and send'}<Send /></Button></div></div><p className="status-note" role="status">{notice}</p>{staleDraft && <div className="draft-warning" role="status"><p>Case context changed. Review the new facts and your draft before sending.</p><Button size="sm" variant="outline" onClick={() => setDrafts(previous => ({ ...previous, [selected]: { text: draft, revision: state.revision } }))}>Confirm reviewed draft</Button></div>}{error && <Alert variant="destructive" className="error-note"><AlertDescription>{error}</AlertDescription></Alert>}</form>
          {demoEnabled && <div className="fixture-controls"><span>Simulate the next customer message in this site only</span><Button size="sm" variant="outline" disabled={busy || !linked || state.parcelB !== 'delivered' || !!state.case?.taskId} onClick={() => void perform({ type: 'send', conversationId: selected, text: CUSTOMER_MESSAGES.evidence, attachment: 'parcel-b' }, 'Sample customer message and parcel B attachment added.')}><MessageSquare />Parcel arrived without the cap</Button></div>}
          </> : <EmptyState title="A case starts with a conversation">Select a conversation from the inbox, or load the first-contact demo below.</EmptyState>}
        </section>
        {panel}
      </div>
      <footer className="demo-bar">{demoEnabled ? <><span className="row"><CalendarDays size={14} />Day {state.day} · 09:00</span><Button variant="outline" size="sm" onClick={() => chooseScene('start')}><RotateCcw />Reset</Button><Button variant="outline" size="sm" onClick={() => chooseScene('first')}>First contact</Button><Button variant="outline" size="sm" disabled={busy} onClick={() => void perform({ type: 'advance' }, 'Demo advanced. Parcel B is marked delivered.')}>Next day<ArrowRight /></Button><Button variant="outline" size="sm" onClick={() => chooseScene('returning')}>Start from Demo 2</Button></> : <><span className="row"><Clock3 size={13} />Frontend preview</span><Link href="/?demo=1" className="button button-ghost button-sm">Open demo controls<ArrowRight size={14} /></Link></>}<span className="demo-state-note">Local fixtures · no APIs · independent from Customer site</span></footer>
    </div>
    <Sheet open={details} onOpenChange={setDetails} title="Case context" description="History, evidence and the suggested next step.">{panel}</Sheet>
    <Sheet open={!!evidence} onOpenChange={open => !open && setEvidence(null)} title={`Parcel ${evidence ?? ''} attachment`} description="Customer source · illustrative sample reference"><EmptyState title="Sample image not supplied">This represents the {evidence === 'A' ? 'shipping label on parcel A' : 'opened parcel B'}. The demo does not upload or verify photos.</EmptyState></Sheet>
    <Sheet open={help} onOpenChange={setHelp} title="Explore the frontend" description="A local, interactive preview of case continuity."><div className="case-section"><h3>Try the returning-customer story</h3><p>Link the conversation to CS001, review what changed, and use the suggested reply. Your approval saves the message locally.</p><p style={{ marginTop: 12 }}>Open demo controls to move between scenes and simulate a new attachment. Refreshing restores the fixture. Customer and CS previews are independent until a backend is connected.</p></div></Sheet>
  </main>;
}
